driverScript:
module.exports = {
  cameraAddress: 1,
  onConnect: function(transport, config) {
    this.cameraAddress = parseInt(config.camera_address, 10) || 1;
    console.log('VISCA Camera Driver Connected (Addr ' + this.cameraAddress + ')');
    engine.setStatus('connected');
    engine.setVariable('camera_power', 'ON');
  },
  onAction: function(transport, actionId, params) {
    var addr = 0x80 | (this.cameraAddress & 0x07);
    if (actionId === 'pan_tilt') {
      var dir = params.direction || 'stop';
      var ps = Math.min(24, Math.max(1, parseInt(params.pan_speed, 10) || 8));
      var ts = Math.min(20, Math.max(1, parseInt(params.tilt_speed, 10) || 8));
      var p1 = 0x03, p2 = 0x03;
      if (dir === 'up') { p1 = 0x03; p2 = 0x01; }
      else if (dir === 'down') { p1 = 0x03; p2 = 0x02; }
      else if (dir === 'left') { p1 = 0x01; p2 = 0x03; }
      else if (dir === 'right') { p1 = 0x02; p2 = 0x03; }
      else if (dir === 'up_left') { p1 = 0x01; p2 = 0x01; }
      else if (dir === 'up_right') { p1 = 0x02; p2 = 0x01; }
      else if (dir === 'down_left') { p1 = 0x01; p2 = 0x02; }
      else if (dir === 'down_right') { p1 = 0x02; p2 = 0x02; }
      else if (dir === 'home') {
        transport.sendBytes([addr, 0x01, 0x06, 0x04, 0xFF]);
        return 'VISCA: Home';
      }
      transport.sendBytes([addr, 0x01, 0x06, 0x01, ps, ts, p1, p2, 0xFF]);
      return 'VISCA: Drive ' + dir;
    }
    if (actionId === 'zoom') {
      var zdir = params.direction || 'stop';
      var zs = Math.min(7, Math.max(0, parseInt(params.speed, 10) || 4));
      if (zdir === 'in') {
        transport.sendBytes([addr, 0x01, 0x04, 0x07, 0x20 | (zs & 0x07), 0xFF]);
      } else if (zdir === 'out') {
        transport.sendBytes([addr, 0x01, 0x04, 0x07, 0x30 | (zs & 0x07), 0xFF]);
      } else {
        transport.sendBytes([addr, 0x01, 0x04, 0x07, 0x00, 0xFF]);
      }
      return 'VISCA: Zoom ' + zdir;
    }
    if (actionId === 'preset_recall') {
      var presetNum = Math.min(127, Math.max(0, parseInt(params.preset_number, 10) || 1));
      transport.sendBytes([addr, 0x01, 0x04, 0x3F, 0x02, presetNum, 0xFF]);
      engine.setVariable('last_preset', String(presetNum));
      return 'VISCA: Recalled Preset ' + presetNum;
    }
    if (actionId === 'preset_store') {
      var storeNum = Math.min(127, Math.max(0, parseInt(params.preset_number, 10) || 1));
      transport.sendBytes([addr, 0x01, 0x04, 0x3F, 0x01, storeNum, 0xFF]);
      return 'VISCA: Stored Preset ' + storeNum;
    }
    return 'VISCA: Unknown action ' + actionId;
  },
  onMessage: function(transport, text, bytes) {
    if (bytes && bytes.length >= 3) {
      if (bytes[1] === 0x41) {
        console.log('VISCA ACK received');
      } else if (bytes[1] === 0x51) {
        console.log('VISCA Completion received');
      }
    }
  },
  onDisconnect: function() {
    engine.setStatus('disconnected');
  }
};
